class Solution:
    def adSequence(self, u: List[str], v: List[str]) -> List[str]:
        g = defaultdict(list)
        for a, b in zip(u, v): g[a].append(b)
        for k in g: g[k].sort(reverse=True)
        out = []; st = ["ABC"]
        while st:
            while g[st[-1]]: st.append(g[st[-1]].pop())
            out.append(st.pop())
        return out[::-1]

